      }

      const hrTile = document.getElementById('tile360HrHrv');
      if (hrTile) {
        if (typeof lastHR !== 'undefined' && lastHR > 0) {
          const hrvStr = (typeof lastHRV !== 'undefined' && lastHRV > 0) ? `${lastHRV} ms` : `-- ms`;
