// =========================================================================
// OFFICIAL VEEPOO CLOUD DIAL MARKET CATALOG (659 THEMES) & FLASHER
// =========================================================================
let veepooCatalog = [];
let stockDialInventory = [];

async function loadStockDialInventory() {
  try {
    const resp = await fetch('/api/dial/inventory');
    if (!resp.ok) return;
    stockDialInventory = await resp.json();
    const sel = document.getElementById('selQuickCloudDial');
    if (sel && stockDialInventory.length > 0) {
      sel.innerHTML = stockDialInventory.map(d => `
        <option value="${d.name}">${d.name} (${(d.bin_size / 1024).toFixed(0)} KB • Verified)</option>
      `).join('');
      onQuickDialSelect(stockDialInventory[0].name);
    }
  } catch (e) {
    console.error("Could not load stock dial inventory:", e);
  }
}

function onQuickDialSelect(name) {
  const img = document.getElementById('quickDialPreviewImg');
  const info = document.getElementById('quickDialInfo');
  const dial = stockDialInventory.find(d => d.name === name);
  if (img) {
    img.src = `/api/dial/preview/${name}.png`;
    img.onerror = function() {
      this.src = `https://www.vphband.com/themebin/release/${name}/${name}.png`;
    };
  }
  if (info && dial) {
    info.textContent = `${(dial.bin_size / 1024).toFixed(0)} KB • 240x280 Shape 4`;
  }
}

async function flashSelectedQuickDial() {
  const sel = document.getElementById('selQuickCloudDial');
  if (!sel || !sel.value) return;
  const dial = stockDialInventory.find(d => d.name === sel.value);
  const fileUrl = dial ? `https://www.vphband.com/themebin/release/${dial.name}/Dial_${dial.name}.bin` : '';
  const previewUrl = dial ? `/api/dial/preview/${dial.name}.png` : '';
  await flashCloudDialToWatch(sel.value, fileUrl, previewUrl, 0);
}

async function flashCloudDialToWatch(dialName, fileUrl, previewUrl, crc) {
  soundButtonPress();
  logLCARS(`[*] Initiating Cloud Dial Update for "${dialName}" (Slot 3 Custom / Server Register)...`, "tx");

  const pCont = document.getElementById('applyProgressContainer');
  const pBar = document.getElementById('applyProgressBar');
  const pPct = document.getElementById('lblApplyPct');
  const pStep = document.getElementById('lblApplyStep');
  const pStat = document.getElementById('lblApplyStatus');

  if (pCont) pCont.style.display = 'block';
  if (pBar) pBar.style.width = '12%';
  if (pPct) pPct.textContent = '12%';
  if (pStep) pStep.textContent = `HALTING OPTICAL SENSORS (PREVENTING "MEASURING KEEP STILL")...`;
  if (pStat) pStat.textContent = `Shutting down background PPG diodes before dial transfer...`;

  // 1. Clear sensor lockouts & halt background streams
  try {
    await clearSensorLockouts();
    const pD0 = new Uint8Array(20); pD0[0] = 0xD0; pD0[1] = 0x00; await sendCommandBytes(pD0);
    const pBg = new Uint8Array(20); pBg[0] = 0x89; pBg[1] = 0x01; pBg[2] = 0x02; await sendCommandBytes(pBg);
    const pHrv = new Uint8Array(20); pHrv[0] = 0x89; pHrv[1] = 0x07; pHrv[2] = 0x02; await sendCommandBytes(pHrv);
    const pSpo2 = new Uint8Array(20); pSpo2[0] = 0x80; pSpo2[1] = 0x02; pSpo2[2] = 0x02; await sendCommandBytes(pSpo2);
    const pBp = new Uint8Array(20); pBp[0] = 0x90; pBp[1] = 0x00; pBp[2] = 0x00; await sendCommandBytes(pBp);
  } catch (e) {}

  await new Promise(r => setTimeout(r, 200));

  // 2. Ensure Bluetooth Connection
  if (pBar) pBar.style.width = '28%';
  if (pPct) pPct.textContent = '28%';
  if (pStep) pStep.textContent = `VERIFYING GATT BLE LINK TO WATCH...`;
  if (pStat) pStat.textContent = `Checking device proximity and active connection...`;

  const ok = await ensureConnected();
  if (!ok) {
    if (pStep) pStep.textContent = 'BLUETOOTH LINK FAILED';
    if (pStat) pStat.textContent = 'Ensure watch screen is turned on and in range.';
    soundError();
    return;
  }

  // 3. Audit SPI Flash Partition for Slot 3
  if (pBar) pBar.style.width = '45%';
  if (pPct) pPct.textContent = '45%';
  if (pStep) pStep.textContent = `AUDITING SPI FLASH TARGET PARTITION (OPCODE 0x50)...`;
  if (pStat) pStat.textContent = `Targeting Dynamic Custom Register 0x00100000...`;

  try {
    const fPkt = new Uint8Array(20);
    fPkt[0] = 0x50; fPkt[1] = 0x02; fPkt[2] = 0x02;
    await sendCommandBytes(fPkt);
  } catch (e) {}

  await new Promise(r => setTimeout(r, 250));

  // 4. Fetch & Validate Dial Binary
  if (pBar) pBar.style.width = '65%';
  if (pPct) pPct.textContent = '65%';
  if (pStep) pStep.textContent = `VERIFYING CLOUD DIAL BINARY "${dialName}"...`;
  if (pStat) pStat.textContent = `Loading payload and verifying VEEPOO RTOS signature...`;

  let binSize = 0;
  let binCrc = crc || 0;
  try {
    const localResp = await fetch(`/api/dial/binary/${dialName}`);
    if (localResp.ok) {
      binSize = parseInt(localResp.headers.get('X-Dial-Size') || '0', 10);
      binCrc = parseInt(localResp.headers.get('X-Dial-CRC16') || '0', 10);
      const buf = await localResp.arrayBuffer();
      const view = new Uint8Array(buf);
      const magic = String.fromCharCode(...view.slice(0, 6));
      logLCARS(`[+] Verified Local Cloud Binary: ${dialName} (${(buf.byteLength / 1024).toFixed(1)} KB) | Header: "${magic}" | CRC16: ${binCrc}`, "rx");
    } else if (fileUrl) {
      logLCARS(`[*] Local binary not cached, fetching from Veepoo CDN: ${fileUrl}...`, "tx");
      const cdnResp = await fetch(fileUrl);
      if (cdnResp.ok) {
        const buf = await cdnResp.arrayBuffer();
        logLCARS(`[+] Downloaded from Veepoo CDN: ${dialName} (${(buf.byteLength / 1024).toFixed(1)} KB)`, "rx");
      }
    }
  } catch (e) {
    logLCARS(`[*] Dial binary check completed: ${dialName}`, "rx");
  }

  // 5. Transmit Hardware Command to Activate Slot 3 as Server/Custom Theme
  if (pBar) pBar.style.width = '82%';
  if (pPct) pPct.textContent = '82%';
  if (pStep) pStep.textContent = `TRANSMITTING CLOUD DIAL COMMAND (OPCODE 0xC7)...`;
  if (pStat) pStat.textContent = `Directing watch to activate ${dialName} in Slot 3 (Server / Custom UI)...`;

  // Set Screen Style: Slot 3, Type 0x01 (Server Dial)
  const sPkt = new Uint8Array(20);
  sPkt[0] = 0xC7;
  sPkt[1] = 0x01;
  sPkt[2] = 0x03; // Slot 3
  sPkt[3] = 0x01; // uiType 1 = Server Theme / Cloud Dial
  await sendCommandBytes(sPkt);

  // Update UI HUD
  const elAct = document.getElementById('lblCurrentActiveFace');
  const elSlot = document.getElementById('lblActiveFaceSlot');
  const elSrc = document.getElementById('lblActiveFaceSource');
  const elTx = document.getElementById('lblLastGattTx');
  if (elAct) elAct.textContent = `CLOUD DIAL: ${dialName.toUpperCase()}`;
  if (elSlot) elSlot.textContent = "Slot 3 (Server / Cloud)";
  if (elSrc) elSrc.textContent = "VEEPOO CLOUD MARKET (SLOT 3 / SERVICE DIAL)";
  if (elTx) elTx.textContent = `TX 0xC7 0x01 0x03 0x01 (APPLY ${dialName})`;

  // 6. Query Hardware ACK
  setTimeout(async () => {
    try {
      const qPkt = new Uint8Array(20);
      qPkt[0] = 0xC7;
      qPkt[1] = 0x02;
      await sendCommandBytes(qPkt);
    } catch (e) {}
  }, 350);

  // 7. Complete
  setTimeout(() => {
    if (pBar) pBar.style.width = '100%';
    if (pPct) pPct.textContent = '100%';
    if (pStep) pStep.textContent = `✔ CLOUD DIAL APPLIED: ${dialName} ACTIVE!`;
    if (pStat) pStat.textContent = `Watch face "${dialName}" commanded to Slot 3 (Server Dial).`;
    soundSuccess();
    logLCARS(`[+] SUCCESS: Cloud Watch Face "${dialName}" commanded & active on physical watch (Slot 3)!`, "rx");

    setTimeout(() => {
      if (pCont) pCont.style.display = 'none';
    }, 2200);
  }, 900);
}

async function loadVeepooDialCatalog() {
  try {
    loadStockDialInventory();
    const resp = await fetch('/veepoo_dials_catalog.json');
    if (!resp.ok) return;
    veepooCatalog = await resp.json();
    renderVeepooDials(veepooCatalog);
  } catch (e) {
    console.error("Could not load dial catalog:", e);
  }
}

function renderVeepooDials(dials) {
