function initFullScanView() {
  if (isFullScanRunning) return;

  const hud = document.getElementById('lblActiveScanStage');
  const cDown = document.getElementById('lblFullScanCountdown');
  const liveVal = document.getElementById('lblFullScanLiveVal');
  if (cDown) cDown.textContent = "--s";
  if (liveVal) liveVal.textContent = "--";

  const vitals = window._latestTelemetry || {};
  const hasAnyVital = Object.keys(vitals).length > 0;

  const repCard = document.getElementById('cardFullScanReport');
  if (repCard) repCard.style.display = 'flex';

  if (!hasAnyVital) {
    if (hud) hud.textContent = "READY: PRESS [START FULL SCAN SEQUENCE] TO BEGIN";
    for (let i = 1; i <= 6; i++) {
      setStageCardState(i, 'idle');
    }
    return;
  }

  if (hud) hud.textContent = "★ RECENT COMPREHENSIVE SCAN AUDIT ONLINE • READY FOR RE-SCAN";
  const hudDesc = document.getElementById('lblActiveScanDetails');
  if (hudDesc) hudDesc.textContent = "Biometric audit loaded from SQLite telemetry database. Press [START FULL SCAN SEQUENCE] for live re-scan.";
  updateOverallProgressBar(100);

  // Stage 1: Glucose
  if (vitals.GLUCOSE && vitals.GLUCOSE.value1 > 0) {
    const g = Math.round(vitals.GLUCOSE.value1);
    setStageCardState(1, 'done', `${g} mg/dL`);
    const gEl = document.getElementById('repValGlucose');
    if (gEl) gEl.innerHTML = `${g} <span style="font-size: 0.9rem;">mg/dL</span>`;
    const gBadge = document.getElementById('repBadgeGlucose');
    if (gBadge) {
      if (g >= 60 && g <= 200) {
        gBadge.textContent = "TIR SAFE (60–200)";
        gBadge.style.color = "var(--lcars-green)";
      } else if (g < 60) {
        gBadge.textContent = "HYPOGLYCEMIA ALERT";
        gBadge.style.color = "#ff5555";
      } else {
        gBadge.textContent = "ELEVATED POSTPRANDIAL";
        gBadge.style.color = "var(--lcars-banana)";
      }
    }
  } else {
    setStageCardState(1, 'idle');
  }

  // Stage 2: Temperature
  if (vitals.TEMPERATURE && vitals.TEMPERATURE.value1 > 0) {
    const bF = vitals.TEMPERATURE.value1;
    const sF = vitals.TEMPERATURE.value2 || (bF - 2.4);
    const bC = (bF - 32) * 5 / 9;
    setStageCardState(2, 'done', `${bF.toFixed(1)}°F`);
    const tEl = document.getElementById('repValTemp');
    if (tEl) tEl.innerHTML = `${bF.toFixed(1)} <span style="font-size: 0.9rem;">°F</span>`;
    const tSub = document.getElementById('repSubTemp');
