async function triggerWatchSyncNow() {
  soundButtonPress();
  logLCARS("[*] Initiating On-Demand Watch Sync. Telemetry pipeline activating...", "tx");

  // 1. Direct BLE Telemetry Dump if watch is connected or in browser cache
  try {
    if (typeof execute15MinWatchDataDump === 'function') {
      await execute15MinWatchDataDump();
    }
  } catch (bleErr) {
    console.warn("BLE dump execution note:", bleErr);
  }

  // 2. Trigger server sync endpoint
  try {
    const resp = await fetch('/api/sync/trigger', { method: 'POST' });
    if (resp.ok) {
      logLCARS("[+] Sync trigger registered by host server.", "rx");
    }
  } catch (e) {
    logLCARS(`Sync Notice: Host server unreachable (${e.message})`, "err");
  }

  // 3. Immediately hydrate all telemetry into UI
  try {
    await fetchTelemetryLatest();
    await fetchTelemetryTimeline();
    if (typeof initFullScanView === 'function') initFullScanView();
    if (typeof renderReportsView === 'function') renderReportsView();
    if (typeof render360HealthView === 'function') render360HealthView();
    if (typeof loadDietHistory === 'function') loadDietHistory();
    if (typeof loadGoalsComplianceReport === 'function') loadGoalsComplianceReport();
  } catch (hydErr) {
    console.warn("Hydration error after sync:", hydErr);
  }

  setTimeout(checkVaultSyncStatus, 1500);
}

