    await sendCommandBytes(cmdBat);
    await new Promise(r => setTimeout(r, 300));

    // Step 3: Real Pedometer & Active Calories / Distance Registers (0x89 0x01 & 0x07)
    if (typeof syncStepData === 'function') {
