# 1. Update updateWorkoutWithSteps and syncStepData, and add propagateStepTelemetry
old_workout = """    function updateWorkoutWithSteps(steps) {
      if (!steps || steps < 0) steps = 0;
      lastSteps = steps;
      const miles = ((steps * 0.7) / 1609.34).toFixed(2);
      const kcal = (steps * 0.04).toFixed(1);

      const elDist = document.getElementById('valWorkoutDist');
