    function propagateStepTelemetry(steps, kcal, miles) {
      const s = (typeof steps === 'number' && !isNaN(steps)) ? Math.max(0, Math.round(steps)) : 0;
      const k = (typeof kcal === 'number' && !isNaN(kcal)) ? Math.max(0, Math.round(kcal)) : Math.round(s * 0.04);
      const m = miles || ((s * 0.7) / 1609.34).toFixed(2);
      lastSteps = s;

      // 1. Tab 02 Vitals Card
      const elStep = document.getElementById('valStepCount');
      if (elStep) elStep.innerHTML = `${s.toLocaleString()} <span style="font-size: 1rem;">steps</span>`;
      const elDist = document.getElementById('valStepDist');
      if (elDist) elDist.innerHTML = `${m} <span style="font-size: 1rem;">miles</span>`;
      const elKcal = document.getElementById('valStepKcal');
      if (elKcal) elKcal.innerHTML = `${k.toLocaleString()} <span style="font-size: 1rem;">kcal</span>`;
      const elGoal = document.getElementById('valStepGoal');
      if (elGoal) elGoal.textContent = `Goal: 2,000 (${Math.round((s / 2000) * 100)}% Met)`;

      // 2. Tab 04 Metabolic 360 Card
      const tileMotion = document.getElementById('tile360Motion');
      if (tileMotion) tileMotion.innerHTML = `${s.toLocaleString()} <span style="font-size: 0.9rem;">steps</span>`;
      const tileSub = document.getElementById('tile360MotionSub');
      if (tileSub) tileSub.textContent = s > 0 ? "Daily Ambulation Recorded" : "Watch Linked (0 Steps Today)";

      // 3. Tab 07 Reports
      const repStep = document.getElementById('repAvgSteps');
      if (repStep) repStep.innerHTML = `${s.toLocaleString()} <span style="font-size: 1rem;">steps</span>`;

      // 4. Tab 11 Goals Console
      const lblDaily = document.getElementById('lblActiveDailySteps');
      if (lblDaily) {
        const pct = Math.min(100, Math.round((s / 8000) * 100));
        lblDaily.textContent = `TOTAL: ${s.toLocaleString()} / 8,000 STEPS (${pct}%)`;
      }

      // 5. Tab 13 Operations / Sport Bay
      updateWorkoutWithSteps(s);

      // 6. Post live pedometer telemetry to server so SQLite reflects current watch state
      if (typeof postTelemetryToServer === 'function') {
        postTelemetryToServer("PEDOMETER", s, k, "steps", "");
      }
    }

    function syncStepData() {
      soundButtonPress();
      logLCARS("[*] Synchronizing real watch pedometer & active calories (0xA8 / 0x07)...", "tx");
      const cmdA8 = new Uint8Array(20);
      cmdA8[0] = 0xA8; cmdA8[1] = 0x00;
      sendCommandBytes(cmdA8);
      const cmd07 = new Uint8Array(20);
      cmd07[0] = 0x07; cmd07[1] = 0x00;
      setTimeout(() => sendCommandBytes(cmd07), 150);

      // Immediately synchronize SPORT-04 workout card with latest walk data
      updateWorkoutWithSteps(lastSteps || 0);
    }"""

