        else if (p.steps < 3000 || p.glucose >= 150) fillCol = '#dc2626';

        svgHtml += `<circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="3" fill="${fillCol}" stroke="#ffffff" stroke-width="0.8" opacity="0.82">
