          <text x="80" y="14" text-anchor="middle" font-size="8" font-family="monospace" fill="#b45309" font-weight="900">⭐ TODAY: ${todaySteps.toLocaleString()} STEPS (${Math.round(todayG)} MG/DL)</text>
        </g>
